<script setup lang="ts">
import {ref,computed,onBeforeUnmount} from 'vue';
const props=defineProps<{latitude:string|number;longitude:string|number;disabled?:boolean}>();const emit=defineEmits<{latitude:[value:string];longitude:[value:string];locating:[value:boolean]}>();const pair=ref(''),message=ref(''),locating=ref(false);let request=0;
const link=computed(()=>{const lat=Number(props.latitude),lng=Number(props.longitude);return String(props.latitude).trim()&&String(props.longitude).trim()&&Number.isFinite(lat)&&Number.isFinite(lng)&&Math.abs(lat)<=90&&Math.abs(lng)<=180?`https://www.google.com/maps?q=${lat},${lng}`:'';});
function apply(){const parts=pair.value.trim().split(/[，、,\s]+/);const [lat,lng]=parts.map(Number);if(parts.length!==2||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180){message.value='請輸入有效的「緯度, 經度」';return;}emit('latitude',lat.toFixed(7));emit('longitude',lng.toFixed(7));message.value='已帶入 GPS 座標';}
function locate(){if(!navigator.geolocation){message.value='此裝置不支援定位';return;}const id=++request;locating.value=true;emit('locating',true);message.value='正在取得目前位置…';navigator.geolocation.getCurrentPosition(p=>{if(id!==request)return;emit('latitude',p.coords.latitude.toFixed(7));emit('longitude',p.coords.longitude.toFixed(7));message.value=`已帶入位置，精準度約 ${Math.round(p.coords.accuracy)} 公尺`;locating.value=false;emit('locating',false);},e=>{if(id!==request)return;message.value=e.code===1?'定位權限遭拒，請允許定位或手動輸入座標':e.code===3?'定位逾時，請重試或手動輸入座標':'無法取得位置，請重試或手動輸入座標';locating.value=false;emit('locating',false);},{enableHighAccuracy:true,timeout:15000,maximumAge:0});}
function clear(){emit('latitude','');emit('longitude','');pair.value='';message.value='已清除 GPS 座標';}onBeforeUnmount(()=>{request++;emit('locating',false);});
</script><template><section class="store-gps"><h2>Google 地圖 GPS</h2><fieldset :disabled="disabled||locating"><div class="gps-pair"><label>貼上座標<input v-model="pair" placeholder="25.033964, 121.564468"></label><button type="button" @click="apply">帶入座標</button><button type="button" @click="locate">使用目前位置</button><button type="button" @click="clear">清除座標</button></div><div class="gps-grid"><label>緯度<input type="number" step="0.0000001" min="-90" max="90" :value="latitude" @input="emit('latitude',($event.target as HTMLInputElement).value)"></label><label>經度<input type="number" step="0.0000001" min="-180" max="180" :value="longitude" @input="emit('longitude',($event.target as HTMLInputElement).value)"></label></div></fieldset><p v-if="message" role="status">{{message}}</p><a v-if="link" :href="link" target="_blank" rel="noopener noreferrer">在 Google Maps 查看座標 ↗</a></section></template><style scoped>fieldset{padding:0;border:0;min-width:0}.store-gps{padding:20px 0;border-top:1px solid var(--line)}h2{font-size:16px}.gps-pair{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.gps-pair label{flex:1;min-width:200px}.gps-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}label{display:grid;gap:8px}input{width:100%;min-width:0}a{text-decoration:underline}@media(max-width:600px){.gps-grid{grid-template-columns:1fr}}</style>
